// ==== SVT-AV1 inv_transforms.c :2449 - svt_av1_round_shift_array_c (verbatim extract; do not edit) ====
void svt_av1_round_shift_array_c(int32_t* arr, int32_t size, int32_t bit) {
    int32_t i;
    if (bit == 0) {
        return;
    } else {
        if (bit > 0) {
            for (i = 0; i < size; i++) {
                arr[i] = round_shift(arr[i], bit);
            }
        } else {
            for (i = 0; i < size; i++) {
                arr[i] = arr[i] * (1 << (-bit));
            }
        }
    }
}

